source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i+1:]:
            if r2 == r1 or abs(r2-r1) != abs(c2-c1):
                continue
            dr = 1 if r2 > r1 else -1
            dc = 1 if c2 > c1 else -1
            segment = []
            r, c = r1, c1
            while True:
                segment.append((r,c))
                if (r,c) == (r2,c2): break
                r += dr; c += dc
            markers = [pt for pt in sixes if pt in segment]
            if dr == dc:
                # Positive-slope 1 segments are marked by perpendicular 6 diagonals.
                for r,c in segment:
                    if out[r][c] != 6: out[r][c] = 1
                for mr,mc in markers:
                    for rr in range(h):
                        cc = mr + mc - rr
                        if 0 <= cc < w and out[rr][cc] != 1:
                            out[rr][cc] = 6
            else:
                # A 6 on a negative-slope segment extends that diagonal across the grid.
                if markers:
                    total = r1+c1
                    for rr in range(h):
                        cc = total-rr
                        if 0 <= cc < w and out[rr][cc] != 1:
                            out[rr][cc] = 6
                else:
                    for r,c in segment:
                        if out[r][c] != 6: out[r][c] = 1
    return out
'''
